UPDATE businesses SET description = 'Allan Y. Brink Pty Ltd is an automotive-engineering and engine-rebuilding business operating from Seccull Avenue in Mayville, Pretoria. The company is classified as an engine-rebuilding service and auto-machine shop, with automotive industry sources also identifying it more broadly as an automotive-engineering operation. Its documented work includes complete engine overhauls, re-sleeving, balancing and camshaft work carried out on classic-car restoration projects. It serves vehicle owners, workshops, classic-car enthusiasts and other automotive businesses that need engine rebuilding, machining or broader engineering work carried out on their vehicles. Allan Y. Brink suits vehicle owners and classic-car enthusiasts looking for a specialist automotive-engineering workshop capable of full engine rebuilds, rather than a general mechanic without machining capability.', description_enriched_at = datetime('now') WHERE slug = 'allan-y-brink-pty-ltd-eloffsdal' AND description = 'Allan Y. Brink is a motor and general engineering workshop in Pretoria specialising in automotive engine overhauls, servicing, maintenance and camshaft work.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
