UPDATE businesses SET description = 'Bestway Design Studio is a furniture and upholstery business in Laudium, offering bespoke design work, upholstery and related home furnishings. The business is classified as a furniture manufacturer, curtain supplier and maker, and woodworking business, giving it a range of furnishing-related specialities under one roof. It serves homeowners, decorators and customers across Laudium and the surrounding area who need custom furniture, upholstery, curtains or other bespoke furnishing work made rather than bought off the shelf. Bestway Design Studio has built up a substantial base of customer reviews over time, reflecting steady local use of its bespoke furniture and upholstery services. Bestway Design Studio suits customers in Laudium looking for a bespoke furniture and upholstery specialist, rather than a general furniture retailer selling only mass-produced pieces.', description_enriched_at = datetime('now') WHERE slug = 'bestway-design-studio-laudium-laudium' AND description = 'Bestway Design Studio is an upholstery and furniture business in Laudium, specialising in sofa and ottoman reupholstering, custom-made curtains and customised headboards.' AND description_enriched_at IS NULL AND length(COALESCE(description, '')) < 700
